<?php
$budgetGroups=['active'=>['Budgets actifs',array_values(array_filter($budgets,static function($b){return $b['status']==='active';}))],'pending'=>['Budgets à valider',array_values(array_filter($budgets,static function($b){return in_array($b['status'],['pending_df','pending_dg','submitted'],true);}))],'preparation'=>['En préparation',array_values(array_filter($budgets,static function($b){return $b['status']==='preparation';}))]];
?>
<div class="butchery-metrics"><?php foreach($budgetGroups as $key=>$group):?><button type="button" class="butchery-kpi" data-workspace-modal-open="budget-kpi-<?=e($key)?>"><strong><?=count($group[1])?></strong><span><?=e($group[0])?></span><i class="bi bi-chevron-right" aria-hidden="true"></i></button><?php endforeach;?></div>
<?php foreach($budgetGroups as $key=>$group):ob_start();?><div class="feed-form-body"><?php if(!$group[1]):?><p class="butchery-empty">Aucun budget dans cette sélection.</p><?php else:?><table class="enterprise-table"><thead><tr><th>Budget</th><th>Site / centre</th><th>Période</th><th>Statut</th><th>Détails</th></tr></thead><tbody><?php foreach($group[1] as $row):?><tr><td><?=e($row['budget_number'])?></td><td><?=e($row['site_code'].' · '.$row['center_code'])?></td><td><?=e($row['period_name'])?></td><td><?=e($budgetLabels[$row['status']]??$row['status'])?></td><td><button type="button" class="btn-secondary" data-workspace-modal-open="budget-detail-<?=e($row['id'])?>">Consulter</button></td></tr><?php endforeach;?></tbody></table><?php endif;?></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button></footer><?php $budgetModal('budget-kpi-'.$key,$group[0],ob_get_clean());endforeach;?>
